// Normalize an Arabic school title for tolerant matching.
// - Strip Arabic diacritics (tashkeel)
// - Fold ة → ه, ى → ي, أ/إ/آ → ا, ؤ → و, ئ → ي
// - Collapse whitespace, drop punctuation, lowercase
export function normalizeArabicTitle(input) {
  if (!input) return '';
  let s = String(input);
  s = s.replace(/[ً-ْٰـ]/g, '');
  s = s.replace(/[أإآا]/g, 'ا')
       .replace(/ى/g, 'ي')
       .replace(/ة/g, 'ه')
       .replace(/ؤ/g, 'و')
       .replace(/ئ/g, 'ي');
  s = s.replace(/[()،.,:;\-—_"'“”‘’`\/\\|]/g, ' ');
  s = s.replace(/\s+/g, ' ').trim().toLowerCase();
  return s;
}
